contract InvMutTest {
    C c;
    constructor() payable { c = new C{value: 10 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint salt) public payable {
        uint t;
        bool ok;
        uint256 v = c.pastBlockTime(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            ok = false;
        } else {
            t = v;
            ok = true;
        }
        assert(ok && t <= block.timestamp);
    }
    receive() external payable {}
}

