pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Roulette c;

    function setUp() public {
        vm.deal(address(this), 10 ether);
        c = new Roulette{value: 10 ether}();
    }

    function _run(uint256 salt) internal {
        uint t;
        bool ok;
        try c.pastBlockTime() returns (uint v) {
            t = v;
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && t <= block.timestamp);
    }

    function testFuzz_run(uint256 salt) public {
        _run(salt);
    }

    receive() external payable {}
}
